// Display fonts embedded as base64 woff2 so a render never depends on the network or on which fonts the machine has.
// Anton, Press Start 2P, Patrick Hand, Bangers and Archivo Black are from Google Fonts under the SIL Open Font License.

export const FONT_FACES: Record<string, string> = {
  anton: "@font-face{font-family:'Anton';src:url(data:font/woff2;base64,) format('woff2');font-weight:400;font-style:normal;}",
  pixel: "@font-face{font-family:'Press Start 2P';src:url(data:font/woff2;base64,) format('woff2');font-weight:400;font-style:normal;}",
  hand: "@font-face{font-family:'Patrick Hand';src:url(data:font/woff2;base64,) format('woff2');font-weight:400;font-style:normal;}",
  bangers: "@font-face{font-family:'Bangers';src:url(data:font/woff2;base64,) format('woff2');font-weight:400;font-style:normal;}",
  archivo: "@font-face{font-family:'Archivo Black';src:url(data:font/woff2;base64,) format('woff2');font-weight:400;font-style:normal;}",
};
